// src/app/middleware/globalErrorHandler.ts
import { ZodError } from "zod";
var globalErrorHandler = (err, _req, res, _next) => {
  if (config_default.node_env === "development") {
    console.error(
      "Error from Global Error Handler:",
      err
    );
  }
  let statusCode = httpStatus.INTERNAL_SERVER_ERROR;
  let message = "Internal Server Error";
  let errors = [];
  if (err instanceof ZodError) {
    statusCode = httpStatus.BAD_REQUEST;
    message = "Validation failed.";
    errors = err.issues.map((issue) => ({
      field: issue.path.join("."),
      message: issue.message
    }));
  } else if (err instanceof prismaNamespace_exports.PrismaClientValidationError) {
    statusCode = httpStatus.BAD_REQUEST;
    message = "Invalid data provided.";
    errors = [
      {
        type: "PrismaValidationError",
        details: "Please check your request fields and field types."
      }
    ];
  } else if (err instanceof prismaNamespace_exports.PrismaClientKnownRequestError) {
    switch (err.code) {
      case "P2002":
        statusCode = httpStatus.CONFLICT;
        message = "A record with this value already exists.";
        errors = [
          {
            type: "DuplicateError",
            details: "Unique field value already exists."
          }
        ];
        break;
      case "P2003":
        statusCode = httpStatus.BAD_REQUEST;
        message = "Foreign key constraint failed.";
        errors = [
          {
            type: "ForeignKeyError",
            details: "The referenced record does not exist."
          }
        ];
        break;
      case "P2025":
        statusCode = httpStatus.NOT_FOUND;
        message = "The requested record was not found.";
        errors = [
          {
            type: "NotFoundError",
            details: "Required record does not exist."
          }
        ];
        break;
      default:
        statusCode = httpStatus.INTERNAL_SERVER_ERROR;
        message = "A database error occurred.";
        errors = [
          {
            type: "DatabaseError",
            details: config_default.node_env === "development" ? err.message : "Unable to process database request."
          }
        ];
    }
  } else if (err instanceof prismaNamespace_exports.PrismaClientInitializationError) {
    statusCode = httpStatus.INTERNAL_SERVER_ERROR;
    message = "Database connection failed.";
    errors = [
      {
        type: "DatabaseError",
        details: config_default.node_env === "development" ? err.message : "Unable to connect to database."
      }
    ];
  } else if (err instanceof prismaNamespace_exports.PrismaClientUnknownRequestError) {
    statusCode = httpStatus.INTERNAL_SERVER_ERROR;
    message = "An error occurred while processing the database request.";
    errors = [
      {
        type: "DatabaseError",
        details: config_default.node_env === "development" ? err.message : "Unknown database error."
      }
    ];
  } else if (err instanceof Error) {
    statusCode = err.statusCode || httpStatus.INTERNAL_SERVER_ERROR;
    message = err.message || "Something went wrong.";
  }
  res.status(statusCode).json({
    success: false,
    message,
    errors
  });
};

