// src/app/module/auth/auth.service.ts
var registerDB = async (payload) => {
  const { name, email, password, phone } = payload;
  const existingUser = await prisma.user.findUnique({
    where: {
      email
    }
  });
  if (existingUser) {
    throw new Error("An account with this email already exists.");
  }
  const hashedPassword = await bcrypt.hash(password, 12);
  const data = {
    name,
    email,
    password: hashedPassword,
    phone,
    role: UserRole.USER,
    status: UserStatus.ACTIVE,
    authProvider: AuthProvider.CRENTIAL,
    emailVerified: false
  };
  const otp = generateOTP();
  const otpkey = `email-verification:${email}`;
  await redisClient.set(
    otpkey,
    otp,
    {
      EX: 5 * 60
    }
  );
  const datakey = `data-email:${email}`;
  await redisClient.set(datakey, JSON.stringify(data), {
    expiration: {
      type: "EX",
      value: 5 * 60
    }
  });
  await nodemailer_default.sendMail({
    from: config_default.smtp_username,
    to: email,
    subject: "Verify Your Email",
    text: `Your OTP is ${otp}`
  });
  return {
    message: "OTP sent successfully"
  };
};
var verificationDB = async (email, OTP) => {
  if (!email && !OTP) {
    throw new Error("email is missing");
  }
  const otpkey = `email-verification:${email}`;
  const datakey = `data-email:${email}`;
  const otp = await redisClient.get(otpkey);
  const data = await redisClient.get(datakey);
  if (otp !== OTP) {
    throw new Error("Invalid OTP");
  }
  if (!data) {
    throw new Error("Invalid Data");
  }
  const result = JSON.parse(data);
  const user = await prisma.user.create({
    data: {
      name: result.name,
      email: result.email,
      password: result.password,
      phone: result.phone,
      role: result.role,
      status: result.status,
      authProvider: result.authProvider,
      emailVerified: true
    },
    omit: { password: true }
  });
  if (user) {
    await redisClient.del(otpkey);
    await redisClient.del(datakey);
  }
  return user;
};
var login = async (payload) => {
  const { email, password } = payload;
  const user = await prisma.user.findUnique({
    where: {
      email
    }
  });
  if (!user) {
    throw new Error("Invalid email or password.");
  }
  if (!user.password) {
    throw new Error(
      "This account does not have a password. Please use Google login."
    );
  }
  const isPasswordMatched = await bcrypt.compare(
    password,
    user.password
  );
  if (!isPasswordMatched) {
    throw new Error("Invalid email or password.");
  }
  if (user.status === "BLOCKED") {
    throw new Error(
      "Your account has been blocked. Please contact support."
    );
  }
  if (user.status === "INACTIVE") {
    throw new Error(
      "Your account is inactive. Please contact support."
    );
  }
  if (!user.emailVerified) {
    throw new Error(
      "Please verify your email before logging in."
    );
  }
  const jwtPayload = {
    userId: user.id,
    email: user.email,
    name: user.name,
    role: user.role
  };
  const accessToken = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_access_secret,
    config_default.jwt_access_expires_in
  );
  const refreshToken3 = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_refresh_secret,
    config_default.jwt_refresh_expires_in
  );
  return {
    accessToken,
    refreshToken: refreshToken3,
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      phone: user.phone,
      role: user.role,
      status: user.status,
      emailVerified: user.emailVerified
    }
  };
};
var refreshToken = async (token) => {
  const verifiedToken = jwtUtils.verifyToken(
    token,
    config_default.jwt_refresh_secret
  );
  if (!verifiedToken.success) {
    throw new Error("Invalid or expired refresh token.");
  }
  const { userId } = verifiedToken.data;
  const user = await prisma.user.findUnique({
    where: {
      id: userId
    }
  });
  if (!user) {
    throw new Error("User not found.");
  }
  if (user.status !== "ACTIVE") {
    throw new Error("Your account is not active.");
  }
  const newAccessToken = jwtUtils.createToken(
    {
      userId: user.id,
      email: user.email,
      name: user.name,
      role: user.role
    },
    config_default.jwt_access_secret,
    config_default.jwt_access_expires_in
  );
  return {
    accessToken: newAccessToken
  };
};
var googleLogin = async (payload) => {
  let googleIdTokenPayload = null;
  try {
    const ticket = await googleClient.verifyIdToken({
      idToken: payload.idToken,
      audience: config_default.google_client_id
    });
    googleIdTokenPayload = ticket.getPayload();
  } catch (error) {
    console.log("Google ID Token Verification Failed", error);
    throw new Error("Invalid Or Expired Google Id Token");
  }
  if (!googleIdTokenPayload) {
    throw new Error("Invalid Or Expired Google Id Token");
  }
  if (!googleIdTokenPayload.email) {
    throw new Error("Google ID Token Payload Does Not Contain Email");
  }
  if (!googleIdTokenPayload.name) {
    throw new Error("Google ID Token Payload Does Not Contain Name");
  }
  const ifPatientExistWithGoogleAuth = await prisma.user.findUnique({
    where: {
      email: googleIdTokenPayload.email,
      role: UserRole.USER,
      googleId: googleIdTokenPayload.sub
    }
  });
  let user = ifPatientExistWithGoogleAuth;
  if (!ifPatientExistWithGoogleAuth) {
    const ifPatientExistWithGoogleCredentials = await prisma.user.findUnique({
      where: {
        email: googleIdTokenPayload.email,
        role: UserRole.USER,
        authProvider: AuthProvider.CRENTIAL
      }
    });
    if (ifPatientExistWithGoogleCredentials) {
      if (!ifPatientExistWithGoogleCredentials.emailVerified) {
        throw new Error("Email is not verified");
      }
      if (ifPatientExistWithGoogleCredentials.status === UserStatus.BLOCKED) {
        throw new Error("User Is Blocked");
      }
      user = await prisma.user.update({
        where: {
          id: ifPatientExistWithGoogleCredentials.id
        },
        data: {
          googleId: googleIdTokenPayload.sub
        }
      });
    } else {
      user = await prisma.user.create({
        data: {
          name: googleIdTokenPayload.name,
          email: googleIdTokenPayload.email,
          role: UserRole.USER,
          googleId: googleIdTokenPayload.sub,
          authProvider: AuthProvider.GOOGLE,
          emailVerified: true,
          status: UserStatus.ACTIVE
        }
      });
    }
  }
  if (!user) {
    throw new Error("User not found");
  }
  if (user.status === UserStatus.BLOCKED) {
    throw new Error("User is blocked");
  }
  const jwtPayload = {
    userId: user.id,
    name: user.name,
    email: user.email,
    role: user.role
  };
  const accessToken = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_access_secret,
    config_default.jwt_access_expires_in
  );
  const refreshToken3 = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_refresh_secret,
    config_default.jwt_refresh_expires_in
  );
  return {
    accessToken,
    refreshToken: refreshToken3
  };
};
