var createAssignment = async (adminId, payload) => {
  const result = await prisma.$transaction(async (tx) => {
    const complaint = await tx.complaint.findUnique({
      where: {
        id: payload.complaintId
      },
      include: {
        assignment: true
      }
    });
    if (!complaint) {
      throw new Error("Complaint not found.");
    }
    if (complaint.status !== ComplaintStatus.PENDING) {
      throw new Error(
        "Only pending complaints can be assigned."
      );
    }
    if (complaint.assignment) {
      throw new Error(
        "This complaint is already assigned."
      );
    }
    const technician = await tx.user.findUnique({
      where: {
        id: payload.technicianId
      }
    });
    if (!technician) {
      throw new Error(
        "Technician not found."
      );
    }
    if (technician.role !== UserRole.TECHNICIAN) {
      throw new Error(
        "Selected user is not a technician."
      );
    }
    if (technician.status !== "ACTIVE") {
      throw new Error(
        "Technician account is not active."
      );
    }
    const assignment = await tx.assignment.create({
      data: {
        complaintId: payload.complaintId,
        technicianId: payload.technicianId,
        assignedById: adminId,
        status: AssignmentStatus.PENDING
      },
      include: {
        complaint: {
          include: {
            area: true
          }
        },
        technician: {
          select: {
            id: true,
            name: true,
            email: true,
            phone: true
          }
        },
        assignedBy: {
          select: {
            id: true,
            name: true,
            email: true
          }
        }
      }
    });
    await tx.complaint.update({
      where: {
        id: payload.complaintId
      },
      data: {
        status: ComplaintStatus.ASSIGNED
      }
    });
    return assignment;
  });
  return result;
};
