var updateAssignment = async (assignmentId, userId, role, payload) => {
  const assignment = await prisma.assignment.findUnique({
    where: {
      id: assignmentId
    },
    include: {
      complaint: true
    }
  });
  if (!assignment) {
    throw new Error(
      "Assignment not found."
    );
  }
  if (role === UserRole.TECHNICIAN) {
    if (assignment.technicianId !== userId) {
      throw new Error(
        "Forbidden. This assignment is not assigned to you."
      );
    }
    const currentStatus = assignment.status;
    const newStatus = payload.status;
    if (newStatus === AssignmentStatus.ACCEPTED) {
      if (currentStatus !== AssignmentStatus.PENDING) {
        throw new Error(
          "Only pending assignments can be accepted."
        );
      }
    }
    if (newStatus === AssignmentStatus.IN_PROGRESS) {
      if (currentStatus !== AssignmentStatus.ACCEPTED) {
        throw new Error(
          "Assignment must be accepted before starting work."
        );
      }
    }
    if (newStatus === AssignmentStatus.COMPLETED) {
      if (currentStatus !== AssignmentStatus.IN_PROGRESS) {
        throw new Error(
          "Assignment must be in progress before completing."
        );
      }
    }
    if (newStatus === AssignmentStatus.REJECTED) {
      if (currentStatus !== AssignmentStatus.PENDING) {
        throw new Error(
          "Only pending assignments can be rejected."
        );
      }
    }
    if (newStatus === AssignmentStatus.CANCELLED) {
      throw new Error(
        "Technician cannot cancel an assignment."
      );
    }
    const result = await prisma.$transaction(
      async (tx) => {
        const updatedAssignment = await tx.assignment.update({
          where: {
            id: assignmentId
          },
          data: {
            status: newStatus
          },
          include: {
            complaint: true,
            technician: {
              select: {
                id: true,
                name: true,
                email: true,
                phone: true
              }
            }
          }
        });
        if (newStatus === AssignmentStatus.COMPLETED) {
          await tx.complaint.update({
            where: {
              id: assignment.complaintId
            },
            data: {
              status: ComplaintStatus.RESOLVED,
              resolvedAt: /* @__PURE__ */ new Date()
            }
          });
        }
        return updatedAssignment;
      }
    );
    return result;
  }
  if (role === UserRole.ADMIN) {
    const result = await prisma.$transaction(
      async (tx) => {
        const updatedAssignment = await tx.assignment.update({
          where: {
            id: assignmentId
          },
          data: {
            status: payload.status
          },
          include: {
            complaint: true,
            technician: {
              select: {
                id: true,
                name: true,
                email: true,
                phone: true
              }
            },
            assignedBy: {
              select: {
                id: true,
                name: true,
                email: true
              }
            }
          }
        });
        if (payload.status === AssignmentStatus.COMPLETED) {
          await tx.complaint.update({
            where: {
              id: assignment.complaintId
            },
            data: {
              status: ComplaintStatus.RESOLVED,
              resolvedAt: /* @__PURE__ */ new Date()
            }
          });
        }
        if (payload.status === AssignmentStatus.CANCELLED || payload.status === AssignmentStatus.REJECTED) {
          await tx.complaint.update({
            where: {
              id: assignment.complaintId
            },
            data: {
              status: ComplaintStatus.PENDING,
              resolvedAt: null
            }
          });
        }
        return updatedAssignment;
      }
    );
    return result;
  }
  throw new Error(
    "Invalid user role."
  );
};
var deleteAssignment = async (assignmentId) => {
  const assignment = await prisma.assignment.findUnique({
    where: {
      id: assignmentId
    }
  });
  if (!assignment) {
    throw new Error(
      "Assignment not found."
    );
  }
  if (assignment.status === AssignmentStatus.IN_PROGRESS) {
    throw new Error(
      "You cannot delete an assignment while work is in progress."
    );
  }
  if (assignment.status === AssignmentStatus.COMPLETED) {
    throw new Error(
      "Completed assignments cannot be deleted."
    );
  }
  await prisma.$transaction(
    async (tx) => {
      await tx.assignment.delete({
        where: {
          id: assignmentId
        }
      });
      await tx.complaint.update({
        where: {
          id: assignment.complaintId
        },
        data: {
          status: ComplaintStatus.PENDING,
          resolvedAt: null
        }
      });
    }
  );
  return null;
};
