// src/app/module/reviews/review.service.ts
var createReview = async (userId, payload) => {
  const complaint = await prisma.complaint.findUnique({
    where: {
      id: payload.complaintId
    },
    include: {
      payment: true,
      review: true
    }
  });
  if (!complaint) {
    throw new Error(
      "Complaint not found."
    );
  }
  if (complaint.userId !== userId) {
    throw new Error(
      "You can only review your own complaint."
    );
  }
  if (complaint.status !== ComplaintStatus.RESOLVED) {
    throw new Error(
      "Review is available only after the complaint is resolved."
    );
  }
  if (!complaint.payment || complaint.payment.status !== PaymentStatus.PAID) {
    throw new Error(
      "Review is available only after successful payment."
    );
  }
  if (complaint.review) {
    throw new Error(
      "This complaint has already been reviewed."
    );
  }
  const review = await prisma.review.create({
    data: {
      userId,
      complaintId: payload.complaintId,
      rating: payload.rating,
      comment: payload.comment
    },
    include: {
      complaint: {
        include: {
          area: true
        }
      },
      user: {
        select: {
          id: true,
          name: true,
          email: true,
          phone: true
        }
      }
    }
  });
  return review;
};
