var updateUserStatus = async (userId, payload) => {
  const user = await prisma.user.findUnique({
    where: {
      id: userId
    }
  });
  if (!user) {
    throw new Error(
      "User not found."
    );
  }
  if (user.role === UserRole.ADMIN && payload.status !== UserStatus.ACTIVE) {
    throw new Error(
      "Admin account cannot be blocked or deactivated."
    );
  }
  const updatedUser = await prisma.user.update({
    where: {
      id: userId
    },
    data: {
      status: payload.status
    },
    select: {
      id: true,
      name: true,
      email: true,
      phone: true,
      role: true,
      status: true,
      emailVerified: true,
      updatedAt: true
    }
  });
  return updatedUser;
};
var updateUserRole = async (userId, payload) => {
  const user = await prisma.user.findUnique({
    where: {
      id: userId
    }
  });
  if (!user) {
    throw new Error(
      "User not found."
    );
  }
  if (user.role === UserRole.ADMIN && payload.role !== UserRole.ADMIN) {
    throw new Error(
      "Admin role cannot be changed."
    );
  }
  const updatedUser = await prisma.user.update({
    where: {
      id: userId
    },
    data: {
      role: payload.role
    },
    select: {
      id: true,
      name: true,
      email: true,
      phone: true,
      role: true,
      status: true,
      emailVerified: true,
      updatedAt: true
    }
  });
  return updatedUser;
};
var deleteUser = async (userId) => {
  const user = await prisma.user.findUnique({
    where: {
      id: userId
    }
  });
  if (!user) {
    throw new Error(
      "User not found."
    );
  }
  if (user.role === UserRole.ADMIN) {
    throw new Error(
      "Admin account cannot be deleted."
    );
  }
  if (user.role === UserRole.TECHNICIAN) {
    const activeAssignment = await prisma.assignment.findFirst({
      where: {
        technicianId: userId,
        status: {
          in: [
            "PENDING",
            "ACCEPTED",
            "IN_PROGRESS"
          ]
        }
      }
    });
    if (activeAssignment) {
      throw new Error(
        "Technician with active assignments cannot be deleted."
      );
    }
  }
  await prisma.user.delete({
    where: {
      id: userId
    }
  });
  return null;
};
var getDashboard = async () => {
  const [
    totalUsers,
    totalTechnicians,
    totalAdmins,
    totalAreas,
    totalSchedules,
    totalComplaints,
    pendingComplaints,
    resolvedComplaints,
    totalAssignments,
    totalPayments,
    paidPayments,
    totalReviews
  ] = await prisma.$transaction([
    prisma.user.count({
      where: {
        role: UserRole.USER
      }
    }),
    prisma.user.count({
      where: {
        role: UserRole.TECHNICIAN
      }
    }),
    prisma.user.count({
      where: {
        role: UserRole.ADMIN
      }
    }),
    prisma.area.count(),
    prisma.loadSheddingSchedule.count(),
    prisma.complaint.count(),
    prisma.complaint.count({
      where: {
        status: ComplaintStatus.PENDING
      }
    }),
    prisma.complaint.count({
      where: {
        status: ComplaintStatus.RESOLVED
      }
    }),
    prisma.assignment.count(),
    prisma.payment.count(),
    prisma.payment.count({
      where: {
        status: PaymentStatus.PAID
      }
    }),
    prisma.review.count()
  ]);
  return {
    users: {
      total: totalUsers
    },
    technicians: {
      total: totalTechnicians
    },
    admins: {
      total: totalAdmins
    },
    areas: {
      total: totalAreas
    },
    schedules: {
      total: totalSchedules
    },
    complaints: {
      total: totalComplaints,
      pending: pendingComplaints,
      resolved: resolvedComplaints
    },
    assignments: {
      total: totalAssignments
    },
    payments: {
      total: totalPayments,
      paid: paidPayments
    },
    reviews: {
      total: totalReviews
    }
  };
};
